    "path": "/__ordinary_jobs_no_external_commands__",
    "maximumAsyncSubjectChildren": 1
  },
  "subjects": [
    {
      "id": 1,
      "purpose": "Sign/leading-space rejection controls; leading-zero acceptance control",
      "source": "{ exit 7; } & child=$!; wait \"+$child\"; printf 'plus:%s\\n' \"$?\"; wait \" $child\"; printf 'leading-space:%s\\n' \"$?\"; wait -- \"-$child\"; printf 'minus-operand:%s\\n' \"$?\"; wait \"0$child\"; printf 'zero-prefix:%s\\n' \"$?\"",
      "sourceSHA256": "5f27a0d606e43031fe74a47e30d4785923f56b7f0579ef7b8f24d1adda3cf217",
      "executed": false
    },
    {
      "id": 2,
      "purpose": "Digit-leading operands with each C-locale trailing whitespace byte",
      "source": "{ exit 7; } & child=$!; for suffix in ' ' $'\\t' $'\\n' $'\\r' $'\\v' $'\\f'; do wait \"$child$suffix\"; printf 'suffix:%s\\n' \"$?\"; done; wait \"$child\"; printf 'plain:%s\\n' \"$?\"",
      "sourceSHA256": "79ece880412c2d2bfe34af332a17c895cde5db147bbb99131c9001f0f4191899",
      "executed": false
    },
    {
      "id": 3,
      "purpose": "Malformed digit-leading operand must stop processing later child operand",
      "source": "{ exit 7; } & child=$!; wait 1x \"$child\"; printf 'mixed:%s\\n' \"$?\"; wait \"$child\"; printf 'retained:%s\\n' \"$?\"",
      "sourceSHA256": "6e9574bfb42225931b959ed36e7c8af58d3533e2d10b78e7f24b9dbec831144d",
      "executed": false
    },
    {
      "id": 4,
      "purpose": "Nondigit invalid operand continues to later child, unlike case3",
      "source": "{ exit 7; } & child=$!; wait x \"$child\"; printf 'mixed:%s\\n' \"$?\"; wait '' \"$child\"; printf 'empty:%s\\n' \"$?\"",
      "sourceSHA256": "8f5d05a5fa0c008944edf159532fac2d433c34831d4b214bf02c682ff419590f",
      "executed": false
    },
    {
      "id": 5,
      "purpose": "Measure configured PID/intmax boundaries; no pid_t-width assumption",
      "source": "for operand in 2147483647 2147483648 9007199254740991 9007199254740992 9223372036854775807 9223372036854775808; do wait \"$operand\"; printf '%s:%s\\n' \"$operand\" \"$?\"; done",
      "sourceSHA256": "5c40258533929e1b4cd919bbde8c1bc0fa6ccb4fe037abc309a2d04ae4a4aa73",
      "executed": false
    },
    {
      "id": 6,
      "purpose": "Option terminator and stop-at-first-operand controls",
      "source": "wait --; printf 'bare:%s\\n' \"$?\"; wait -- --; printf 'second-dashdash:%s\\n' \"$?\"; wait -- -1; printf 'negative-operand:%s\\n' \"$?\"; wait 0 -z; printf 'late-option:%s\\n' \"$?\"",
      "sourceSHA256": "31ceed621437d8f8cbf56b39562a192e5698ebec9e0f1027f0440def1964440a",
      "executed": false
    },
    {
      "id": 7,
      "purpose": "Unknown clusters; mixed -f prefix separately marks pending-option interaction",
      "source": "wait -zx; printf 'zx:%s\\n' \"$?\"; wait -xz; printf 'xz:%s\\n' \"$?\"; wait -fz; printf 'fz:%s\\n' \"$?\"",
      "sourceSHA256": "d70977fcd49923fae6f8c85189a01f3c48420cf59cc7c98c3c042f10f01ce425",
      "executed": false
    },
    {
      "id": 8,
      "purpose": "Invalid option diagnostic uses one raw byte, not decoded character",
      "source": "wait $'-\\xffz'; printf 'raw:%s\\n' \"$?\"; wait $'-\\xc3\\xa9z'; printf 'utf8:%s\\n' \"$?\"",
      "sourceSHA256": "24d5faf2acb93ed0b101f9bdf1eb8a3df19bc2049b28cd68664e0d8999222f53",
      "executed": false
    }
  ]
}

